package com.cenedu.backend.ai.problem.render;
import com.cenedu.backend.domain.problem.authoring.diagram.*; import com.cenedu.backend.domain.problem.authoring.semantic.evaluation.SemanticResolvedValue; import java.util.*;
public final class NumberLineSvgRenderer { public String render(NumberLineDiagramSpecV1 s){return render(s,Map.of());} public String render(NumberLineDiagramSpecV1 s,Map<String,SemanticResolvedValue> values){int p=s.viewport().padding(),end=s.viewport().width()-p,y=s.viewport().height()/2;double min=num(values,s.minKey(),0),max=num(values,s.maxKey(),10),range=max-min;var b=new StringBuilder("<line x1=\"").append(p).append("\" y1=\"").append(y).append("\" x2=\"").append(end).append("\" y2=\"").append(y).append("\" stroke=\"#000000\"/>");if(s.startArrow())b.append("<path d=\"M ").append(p).append(" ").append(y).append(" l 8 -5 M ").append(p).append(" ").append(y).append(" l 8 5\" stroke=\"#000000\"/>");if(s.endArrow())b.append("<path d=\"M ").append(end).append(" ").append(y).append(" l -8 -5 M ").append(end).append(" ").append(y).append(" l -8 5\" stroke=\"#000000\"/>");double tick=num(values,s.tickIntervalKey(),0);if(tick>0&&range>0)for(double value=min;value<=max;value+=tick){int x=x(value,min,max,p,end);b.append("<line x1=\"").append(x).append("\" y1=\"").append(y-5).append("\" x2=\"").append(x).append("\" y2=\"").append(y+5).append("\" stroke=\"#000000\"/>");}for(var point:s.points()){int x=x(num(values,point.positionKey(),min),min,max,p,end);b.append("<circle cx=\"").append(x).append("\" cy=\"").append(y).append("\" r=\"5\" fill=\"").append(point.marker()==PointMarker.CLOSED_CIRCLE?"#000000":"#FFFFFF").append("\" stroke=\"#000000\"/>");}for(var in:s.intervals()){int x1=x(num(values,in.startKey(),min),min,max,p,end),x2=x(num(values,in.endKey(),max),min,max,p,end);b.append("<line x1=\"").append(x1).append("\" y1=\"").append(y).append("\" x2=\"").append(x2).append("\" y2=\"").append(y).append("\" stroke=\"#FF0000\" stroke-width=\"2\"/>");}return b.toString();}private int x(double value,double min,double max,int p,int end){return (int)(p+(value-min)/(max==min?1:max-min)*(end-p));}private double num(Map<String,SemanticResolvedValue> v,String k,double d){try{return Double.parseDouble(v.get(k).canonicalValue());}catch(Exception e){return d;}} }
